.if-button{background:var(--if-orange);border:1px solid var(--if-orange);color:#fff;font-size:12px;font-weight:700;gap:28px;min-height:48px;min-width:154px;padding:0 15px;transition:.2s}.if-button:hover{background:#e93207;transform:translateY(-2px)}.if-button.is-inverse{background:var(--if-ink);border-color:var(--if-ink);color:#fff}.if-label{font-size:10px;font-weight:800;gap:9px;letter-spacing:.15em;text-transform:uppercase}.if-label span{background:var(--if-orange);height:4px;width:4px}.if-label.is-light{color:#fff}
.if-hero{background:#090909;color:#fff;min-height:760px;padding:0 max(28px,calc((100vw - 1320px)/2)) 30px}.if-hero-image{inset:0}.if-hero-shade{background:linear-gradient(90deg,rgba(0,0,0,.88) 0%,rgba(0,0,0,.42) 55%,rgba(0,0,0,.25)),linear-gradient(0deg,rgba(0,0,0,.65),transparent 55%);inset:0}.if-header{border-bottom:1px solid rgba(255,255,255,.28);height:84px;z-index:2}.if-brand{gap:10px}.if-brand>span{background:var(--if-orange);height:34px;width:34px}.if-brand b{font-size:17px}.if-header nav{gap:36px}.if-header nav a{font-size:12px}.if-header nav a:hover{color:var(--if-orange)}.if-mobile-menu{display:none}.if-hero-copy{max-width:740px;padding:80px 0 65px}.if-hero-copy h1{font-size:clamp(72px,8.5vw,128px);margin:28px 0}.if-hero-copy>p:last-child{color:#d2d2d2;font-size:16px;max-width:580px}.if-hero-foot{border-top:1px solid rgba(255,255,255,.25);grid-template-columns:repeat(3,1fr) auto;padding-top:25px}.if-hero-foot>span,.if-hero-foot>a{align-items:center;display:flex;font-size:11px;gap:9px;text-transform:uppercase}.if-hero-foot>a{color:#ccc}
.if-about{gap:64px;grid-template-columns:.9fr .8fr 1fr;margin:auto;max-width:1320px;padding:130px 28px}.if-about h2,.if-section-head h2{font-size:clamp(42px,5vw,72px);margin-top:22px}.if-about-copy{color:#555}.if-about-copy>p+ p{margin-top:18px}.if-about-copy .if-button{margin-top:28px}.if-about figure{height:440px}.if-about figcaption{align-items:center;background:var(--if-orange);bottom:0;color:#fff;display:flex;gap:14px;left:0;padding:20px}.if-about figcaption strong{font-size:36px}.if-about figcaption span{font-size:10px;text-transform:uppercase}
.if-stats{background:#ecece9;border-bottom:1px solid var(--if-line);border-top:1px solid var(--if-line);grid-template-columns:repeat(3,1fr);padding:68px max(28px,calc((100vw - 1320px)/2))}.if-stats>div{align-items:flex-end;border-right:1px solid var(--if-line);display:flex;gap:24px;padding:0 55px}.if-stats>div:first-child{padding-left:0}.if-stats>div:last-child{border:0}.if-stats strong{font-size:76px;letter-spacing:-.06em;line-height:.8}.if-stats span{color:#676767;font-size:10px;text-transform:uppercase}
.if-dark{background:var(--if-ink);color:#fff;padding-left:max(28px,calc((100vw - 1320px)/2));padding-right:max(28px,calc((100vw - 1320px)/2))}.if-services{padding-bottom:120px;padding-top:120px}.if-section-head{gap:50px}.if-section-head>p{color:#777;max-width:410px}.if-dark .if-section-head>p{color:#aaa}.if-service-grid{gap:12px;grid-template-columns:repeat(3,1fr);margin-top:62px}.if-service-card{height:500px}.if-service-card>img{inset:0;transition:.45s}.if-service-card:hover>img{transform:scale(1.035)}.if-service-card>div{background:linear-gradient(0deg,rgba(0,0,0,.92),transparent 72%);inset:0}.if-service-card>span{left:22px;position:absolute;top:20px}.if-service-card>section{bottom:0;left:0;padding:28px;right:0}.if-service-card h3{font-size:28px}.if-service-card p{color:#ccc;font-size:12px;margin:12px 52px 0 0}.if-service-card section>a{background:var(--if-orange);bottom:28px;height:42px;position:absolute;right:24px;width:42px}
.if-process{gap:100px;grid-template-columns:.8fr 1.2fr;padding-bottom:110px;padding-top:20px}.if-process h2{font-size:clamp(42px,5vw,70px);margin:22px 0}.if-process>div>p:last-child{color:#999;max-width:470px}.if-process ol{list-style:none;margin:0;padding:0}.if-process li{align-items:center;border-top:1px solid #333;display:grid;gap:22px;grid-template-columns:32px 1fr auto;padding:26px 0}.if-process li:last-child{border-bottom:1px solid #333}.if-process li>span{color:var(--if-orange);font-size:11px}.if-process h3{font-size:20px}.if-process li p{color:#888;font-size:12px;margin-top:5px}.if-orange-cta{background:var(--if-orange);color:#fff;margin:auto;max-width:1100px;padding:42px 46px;transform:translateY(1px)}.if-orange-cta h2{font-size:36px}.if-orange-cta .if-button{background:#fff;border-color:#fff;color:#111}
.if-values{margin:auto;max-width:1320px;padding:130px 28px}.if-value-grid{border-top:1px solid var(--if-line);grid-template-columns:repeat(4,1fr);margin-top:55px}.if-value{border-right:1px solid var(--if-line);padding:38px 30px 15px 0}.if-value+.if-value{padding-left:30px}.if-value:last-child{border:0}.if-value h3{font-size:19px;margin:25px 0 12px}.if-value p{color:#666;font-size:12px}
.if-projects{background:#eaeae7;padding:115px max(28px,calc((100vw - 1320px)/2))}.if-project-list{border-top:1px solid var(--if-line);margin-top:55px}.if-project-list>a{border-bottom:1px solid var(--if-line);gap:20px;grid-template-columns:42px 1fr 1fr 70px 20px;min-height:78px}.if-project-list>a:hover h3{color:var(--if-orange)}.if-project-list span,.if-project-list time{font-size:10px}.if-project-list h3{font-size:22px}.if-project-list p{color:#666;font-size:12px}
.if-proof{margin:auto;max-width:1320px;padding:120px 28px}.if-proof-grid{grid-template-columns:1.25fr .85fr .85fr;margin-top:55px}.if-proof figure{min-height:500px}.if-proof figcaption{background:#fff;bottom:20px;font-size:11px;left:20px;padding:12px 15px}.if-proof blockquote{background:#f0f0ed;margin:0;padding:44px}.if-proof blockquote.is-accent{background:var(--if-orange);color:#fff}.if-proof blockquote>span{font-size:68px;line-height:1}.if-proof blockquote>p{font-size:20px;line-height:1.45}.if-proof blockquote footer{display:flex;flex-direction:column;margin-top:65px}.if-proof blockquote small{font-size:10px;margin-top:4px;opacity:.65}
.if-insights{padding-bottom:120px;padding-top:120px}.if-insight-grid{gap:18px;grid-template-columns:repeat(3,1fr);margin-top:55px}.if-insight-grid img{height:260px}.if-insight-grid small{color:var(--if-orange);display:block;font-size:10px;margin-top:20px;text-transform:uppercase}.if-insight-grid h3{font-size:21px;margin:10px 0 22px}.if-insight-grid a{color:#bbb;font-size:11px;gap:8px}
.if-contact{color:#fff;min-height:560px;padding:90px 24px}.if-contact>img{inset:0}.if-contact>div:nth-of-type(1){background:rgba(0,0,0,.58);inset:0}.if-contact>div:last-child{max-width:820px}.if-contact .if-label{justify-content:center}.if-contact h2{font-size:clamp(52px,7vw,92px);margin:28px 0 18px}.if-contact p{color:#ddd}.if-contact-button{background:#fff;color:#111;font-size:12px;font-weight:700;gap:45px;margin-top:34px;min-height:50px;padding:0 16px}
.if-footer{background:#060606;color:#fff;padding:80px max(28px,calc((100vw - 1320px)/2)) 28px}.if-footer-main{gap:70px;grid-template-columns:1.3fr .6fr .8fr 1.15fr}.if-footer-main>div{display:flex;flex-direction:column;gap:10px}.if-footer-main>div:first-child p{color:#777;font-size:12px;margin-top:14px;max-width:280px}.if-footer-main>div:not(:first-child)>b{font-size:11px;margin-bottom:9px;text-transform:uppercase}.if-footer-main>div:not(:first-child)>a:not(.if-button){color:#888;font-size:11px}.if-footer .if-button{margin-top:8px}.if-footer-bottom{border-top:1px solid #242424;color:#777;font-size:10px;margin-top:65px;padding-top:25px}.if-footer-bottom a{gap:8px}
@media(max-width:1000px){.if-header nav{display:none}.if-header>.if-button{display:none}.if-mobile-menu{display:block;position:relative}.if-mobile-menu summary{cursor:pointer;display:flex;list-style:none}.if-mobile-menu>div{background:#fff;color:#111;display:flex;flex-direction:column;min-width:190px;padding:16px;position:absolute;right:0;top:34px}.if-mobile-menu a{padding:9px}.if-about{grid-template-columns:1fr 1fr}.if-about figure{grid-column:1/-1}.if-stats>div{align-items:flex-start;flex-direction:column;padding:0 30px}.if-service-grid{grid-template-columns:1fr 1fr}.if-service-card:last-child{grid-column:1/-1}.if-process{gap:55px;grid-template-columns:1fr}.if-value-grid{grid-template-columns:1fr 1fr}.if-value:nth-child(2){border-right:0}.if-value:nth-child(-n+2){border-bottom:1px solid var(--if-line)}.if-proof-grid{grid-template-columns:1fr 1fr}.if-proof figure{grid-column:1/-1}.if-footer-main{grid-template-columns:1fr 1fr}.if-footer-main>div:first-child{grid-column:1/-1}}
@media(max-width:680px){.if-hero{min-height:700px;padding-left:20px;padding-right:20px}.if-header{height:70px}.if-hero-copy{padding:80px 0 50px}.if-hero-copy h1{font-size:64px}.if-hero-foot{gap:14px;grid-template-columns:1fr 1fr}.if-hero-foot>a{display:none}.if-about{display:block;padding:90px 20px}.if-about-copy{margin:35px 0 45px}.if-about figure{height:360px}.if-stats{grid-template-columns:1fr;padding:25px 20px}.if-stats>div{align-items:center;border-bottom:1px solid var(--if-line);border-right:0;flex-direction:row;padding:28px 0}.if-stats>div:last-child{border-bottom:0}.if-stats strong{font-size:60px}.if-dark{padding-left:20px;padding-right:20px}.if-services{padding-bottom:90px;padding-top:90px}.if-section-head{align-items:flex-start;flex-direction:column}.if-service-grid{grid-template-columns:1fr}.if-service-card,.if-service-card:last-child{grid-column:auto;height:410px}.if-process{padding-bottom:80px}.if-orange-cta{align-items:flex-start;flex-direction:column;gap:28px;padding:34px 20px}.if-orange-cta h2{font-size:29px}.if-values,.if-proof{padding:90px 20px}.if-value-grid{grid-template-columns:1fr}.if-value,.if-value+.if-value{border-bottom:1px solid var(--if-line);border-right:0;padding:30px 0}.if-projects{padding:90px 20px}.if-project-list>a{grid-template-columns:30px 1fr 18px;padding:18px 0}.if-project-list p,.if-project-list time{display:none}.if-proof-grid{display:block}.if-proof figure{min-height:390px}.if-proof blockquote{padding:34px 24px}.if-insights{padding-bottom:90px;padding-top:90px}.if-insight-grid{grid-template-columns:1fr}.if-contact{min-height:520px}.if-contact h2{font-size:51px}.if-contact-button{gap:18px;max-width:100%;overflow:hidden}.if-footer{padding:65px 20px 25px}.if-footer-main{gap:40px;grid-template-columns:1fr 1fr}.if-footer-main>div:last-child{grid-column:1/-1}.if-footer-bottom{align-items:flex-start;flex-direction:column;gap:12px}}
@media(max-width:360px){.if-hero-copy h1{font-size:54px}.if-hero-foot{grid-template-columns:1fr}.if-about h2,.if-section-head h2{font-size:39px}.if-contact h2{font-size:43px}.if-contact-button{font-size:10px}.if-footer-main{grid-template-columns:1fr}.if-footer-main>div:first-child,.if-footer-main>div:last-child{grid-column:auto}}

/* Coordiation motion utilities and footer isolation. */
:where(.industrial-forge .co-transition){transition-property:color,background-color,border-color,opacity,box-shadow,transform}
:where(.industrial-forge .co-duration-300){transition-duration:300ms}
:where(.industrial-forge .co-ease-out){transition-timing-function:cubic-bezier(0,0,.2,1)}
@keyframes co-pulse{0%,100%{opacity:1}50%{opacity:.45}}
@media(prefers-reduced-motion:no-preference){:where(.industrial-forge .motion-safe\:co-animate-pulse){animation:co-pulse 2s cubic-bezier(.4,0,.6,1) infinite}}
@media(prefers-reduced-motion:reduce){:where(.industrial-forge .motion-reduce\:co-animate-none){animation:none!important;transition:none!important}}

.industrial-forge .if-button{color:#fff}
.industrial-forge .if-button.is-inverse{color:#fff}
.industrial-forge .if-button.is-light{background:#fff;border-color:#fff;color:#111}
.industrial-forge .if-button.is-light:hover{background:#111;border-color:#111;color:#fff}
.if-service-card:hover{transform:translateY(-6px)}
.if-service-card section>a:hover{background:#fff;transform:rotate(8deg)}
.industrial-forge .if-contact-button{color:#111}
.industrial-forge .if-contact-button:hover{background:var(--if-orange);color:#fff;transform:translateY(-3px)}

.if-proof blockquote footer{align-items:flex-start;border:0;color:inherit;font-size:inherit;grid-template-columns:none;min-height:0;padding:0}
.if-footer{align-items:initial;border-top:0;display:block;font-size:15px;grid-template-columns:none;min-height:0;padding:88px max(28px,calc((100vw - 1320px)/2)) 28px}
.if-footer-main{gap:clamp(40px,6vw,92px);grid-template-columns:minmax(260px,1.25fr) minmax(110px,.45fr) minmax(220px,.8fr) minmax(250px,1fr);width:100%}
.if-footer-main>div{min-width:0}
.if-footer-identity{padding-right:20px}
.if-footer-brand{align-self:flex-start;gap:13px}
.if-footer-brand>span{flex:0 0 42px;height:42px;width:42px}
.if-footer-brand b{font-size:20px;line-height:1;white-space:nowrap}
.if-footer-main>div:first-child p{color:#858585;font-size:13px;line-height:1.7;margin-top:17px;max-width:300px}
.if-footer-main>div:not(:first-child)>b{font-size:11px;line-height:1.5;margin-bottom:10px}
.industrial-forge .if-footer-main>div:not(:first-child)>a:not(.if-button){color:#999;font-size:12px;overflow-wrap:anywhere;transition:color .2s ease,transform .2s ease}
.industrial-forge .if-footer-main>div:not(:first-child)>a:not(.if-button):hover{color:#fff;transform:translateX(3px)}
.if-footer-action>span{color:var(--if-orange);font-size:10px;letter-spacing:.12em;text-transform:uppercase}
.if-footer .if-button{align-self:flex-start;margin-top:12px;min-width:190px}
.if-footer-bottom{border-top:1px solid #242424;color:#777;font-size:10px;margin-top:72px;padding-top:25px;width:100%}
.if-footer-bottom>div{gap:24px}
.industrial-forge .if-footer-bottom a{color:#888;gap:8px;transition:color .2s ease}
.industrial-forge .if-footer-bottom a:hover{color:#fff}

@media(max-width:1000px){.if-footer-main{gap:52px;grid-template-columns:1.2fr .7fr 1fr}.if-footer-main>div:first-child{grid-column:auto}.if-footer-main>div:last-child{grid-column:1/-1}.if-footer-action{border-top:1px solid #242424;padding-top:36px}}
@media(max-width:680px){.if-footer{padding:65px 20px 25px}.if-footer-main{gap:40px;grid-template-columns:1fr 1fr}.if-footer-main>div:first-child,.if-footer-main>div:last-child{grid-column:1/-1}.if-footer-bottom{align-items:flex-start;flex-direction:column;gap:18px}.if-footer-bottom>div{flex-wrap:wrap;gap:16px 22px}.industrial-forge .if-contact-button{gap:18px;max-width:100%;overflow:hidden}}
@media(max-width:360px){.if-footer-main{grid-template-columns:1fr}.if-footer-main>div:first-child,.if-footer-main>div:last-child{grid-column:auto}.if-footer-brand b{font-size:18px}}

const icons = {
  "arrow-right": "/icons/solar-linear/arrow-right.svg",
  "arrow-to-top-right": "/icons/solar-linear/arrow-to-top-right.svg",
  "hamburger-menu": "/icons/solar-linear/hamburger-menu.svg",
  bolt: "/icons/solar-linear/bolt.svg",
  "shield-check": "/icons/solar-linear/shield-check.svg",
  "graph-new-up": "/icons/solar-linear/graph-new-up.svg",
  "map-point": "/icons/solar-linear/map-point.svg",
  "settings-minimalistic": "/icons/solar-linear/settings-minimalistic.svg",
  "buildings-2": "/icons/solar-linear/buildings-2.svg",
  target: "/icons/solar-linear/target.svg",
  "clock-circle": "/icons/solar-linear/clock-circle.svg",
  "users-group-rounded": "/icons/solar-linear/users-group-rounded.svg",
  letter: "/icons/solar-linear/letter.svg",
} as const;

export type ThemeIconName = keyof typeof icons;

export default function ThemeIcon({ name, size = 18, tone = "dark" }: { name: ThemeIconName; size?: number; tone?: "dark" | "light" | "accent" }) {
  return <img className={`if-icon if-icon-${tone}`} src={icons[name]} width={size} height={size} alt="" aria-hidden="true" />;
}

import type { ReactNode } from "react";
import ThemeIcon, { type ThemeIconName } from "./ThemeIcon";

export function ForgeButton({ href, children, inverse = false, light = false }: { href: string; children: ReactNode; inverse?: boolean; light?: boolean }) {
  return <a className={`if-button co-inline-flex co-items-center co-justify-between co-transition co-duration-300 co-ease-out motion-reduce:co-animate-none${inverse ? " is-inverse" : ""}${light ? " is-light" : ""}`} href={href}>{children}<ThemeIcon name="arrow-right" size={17} tone={light ? "dark" : "light"} /></a>;
}

export function SectionLabel({ children, light = false }: { children: ReactNode; light?: boolean }) {
  return <p className={`if-label co-flex co-items-center${light ? " is-light" : ""}`}><span className="motion-safe:co-animate-pulse motion-reduce:co-animate-none" />{children}</p>;
}

export function ServiceCard({ index, title, copy, image }: { index: string; title: string; copy: string; image: string }) {
  return <article className="if-service-card co-relative co-overflow-hidden co-transition co-duration-300 co-ease-out"><img className="co-absolute co-w-full co-h-full co-object-cover co-transition co-duration-300 co-ease-out" src={image} alt="" /><div className="co-absolute" /><span>{index}</span><section className="co-absolute"><h3>{title}</h3><p>{copy}</p><a className="co-inline-flex co-items-center co-justify-center co-transition co-duration-300 co-ease-out" href="#contact" aria-label={`Explore ${title}`}><ThemeIcon name="arrow-to-top-right" size={17} tone="light" /></a></section></article>;
}

export function ValueCard({ icon, title, copy }: { icon: ThemeIconName; title: string; copy: string }) {
  return <article className="if-value"><ThemeIcon name={icon} size={24} tone="accent" /><h3>{title}</h3><p>{copy}</p></article>;
}
